<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\{ActivationRequest,AuditLog,Product}; use App\Services\DomainNormalizer; use Illuminate\Http\{JsonResponse,Request}; use Illuminate\Support\Facades\Crypt; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException; use InvalidArgumentException;
class ActivationRequestController extends Controller {
public function store(Request $r,DomainNormalizer $domains):JsonResponse {if(strlen($r->getContent())>8192)return response()->json(['message'=>'Payload too large.'],413);$v=$r->validate(['product'=>'required|string|max:64','version'=>'required|string|max:64','license_type'=>'required|string|max:64','installation_uuid'=>'required|uuid','domain'=>'required|string|max:253','environment'=>'required|in:production,staging,local,development,testing','nonce'=>'required|string|min:16|max:128']);$product=Product::where(['slug'=>$v['product'],'status'=>'active'])->first();$edition=$product?->editions()->where(['license_type'=>$v['license_type'],'status'=>'active'])->first();if(!$edition)throw ValidationException::withMessages(['product'=>'The product or edition is unavailable.']);try{$domain=$domains->normalize($v['domain']);}catch(InvalidArgumentException){throw ValidationException::withMessages(['domain'=>'The domain is invalid.']);}$token='BRQ-'.implode('-',str_split(strtoupper(substr(strtr(base64_encode(random_bytes(9)),'+/','XZ'),0,12)),4));$a=new ActivationRequest;$a->forceFill(['request_id'=>(string)Str::uuid(),'request_token_hash'=>hash('sha256',$token),'request_token_prefix'=>substr($token,0,8),'product_id'=>$product->id,'product_edition_id'=>$edition->id,'installation_uuid'=>$v['installation_uuid'],'normalized_domain'=>$domain,'environment'=>$v['environment'],'application_version'=>$v['version'],'nonce_hash'=>hash('sha256',$v['nonce']),'status'=>'pending','expires_at'=>now()->addMinutes(config('license.request_ttl'))])->save();AuditLog::create(['action'=>'activation.request_created','entity_type'=>'activation_request','entity_id'=>(string)$a->id,'safe_summary'=>'Activation request created','correlation_id'=>(string)Str::uuid()]);return response()->json(['request_id'=>$a->request_id,'request_token'=>$token,'status'=>'pending','expires_at'=>$a->expires_at->toIso8601String(),'portal_url'=>url('/activate')],201);}
public function status(Request $r,string $requestId):JsonResponse {$v=$r->validate(['request_token'=>'required|string|max:64','installation_uuid'=>'required|uuid']);$a=ActivationRequest::where('request_id',$requestId)->firstOrFail();if(!hash_equals($a->request_token_hash,hash('sha256',$v['request_token']))||!hash_equals(strtolower($a->installation_uuid),strtolower($v['installation_uuid'])))return response()->json(['message'=>'Invalid activation proof.'],403);if($a->status==='pending'&&$a->expires_at->isPast()){$a->update(['status'=>'expired']);}if($a->status==='approved'){ $signed=$a->signed_entitlement; $a->update(['status'=>'completed','completed_at'=>now()]); AuditLog::create(['action'=>'activation.completed','entity_type'=>'activation_request','entity_id'=>(string)$a->id,'safe_summary'=>'Signed license delivered','correlation_id'=>(string)Str::uuid()]); return response()->json(['status'=>'approved','signed_license'=>$signed]); }if($a->status==='rejected')return response()->json(['status'=>'rejected','failure_code'=>$a->failure_code,'safe_message'=>$a->safe_failure_message]);if($a->status==='expired')return response()->json(['status'=>'expired','safe_message'=>'The activation request has expired.']);return response()->json(['status'=>$a->status]);}
}
